check($m->conversationMedia($a,$id,'documents',null,30,'WEEKEND')['items'][0]['id']===$doc['id'],'case insensitive filename search');check($m->conversationMedia($a,$id,'documents',null,30,'absent')['items']===[],'search excludes nonmatching document');denied(fn()=>$m->conversationMedia($a,$id,'documents',null,30,'x'));
check(array_column($m->conversationMedia($a,$id,'visual')['items'],'id')===[$photo['id']],'image MIME classified as visual');
