$one=$m->sendMessage($id,$b,'New https://example.test/one','media_catalog_link_one');$two=$m->sendMessage($id,$b,'Next https://example.test/two','media_catalog_link_two');
$p=$m->conversationMedia($a,$id,'links',null,1);$next=$m->conversationMedia($a,$id,'links',$p['next_before'],1);check($p['items'][0]['id']===$two['id']&&$next['items'][0]['id']===$one['id'],'result limit cursor exclusive and newest first');
